/**
 * Generic newline-delimited JSON-RPC stdio MCP server for packaged
 * `defineConnection({ tools })` modules. Bundled into `node -e` so a
 * repo-less cloud VM can spawn it. Keep this file free of framework
 * barrels and the official MCP SDK.
 */
import { isRecord } from "./is-record.js";
const PROTOCOL_VERSION = "2025-03-26";
function isJsonRpcId(value) {
    return value === null || typeof value === "string" || typeof value === "number";
}
function readJsonRpc(value) {
    if (!isRecord(value)) {
        return undefined;
    }
    const message = {};
    if (typeof value.jsonrpc === "string") {
        message.jsonrpc = value.jsonrpc;
    }
    if (isJsonRpcId(value.id)) {
        message.id = value.id;
    }
    if (typeof value.method === "string") {
        message.method = value.method;
    }
    if (isRecord(value.params)) {
        message.params = value.params;
    }
    return message;
}
function write(message) {
    process.stdout.write(`${JSON.stringify(message)}\n`);
}
function stringifyResult(result) {
    if (typeof result === "string") {
        return result;
    }
    return JSON.stringify(result);
}
function isMcpEnvelope(result) {
    return (typeof result === "object" &&
        result !== null &&
        "content" in result &&
        Array.isArray(result.content));
}
function validateInput(tool, args) {
    const record = isRecord(args) ? args : {};
    const schema = tool.inputSchema;
    if (schema === undefined || typeof schema.safeParse !== "function") {
        return { ok: true, value: record };
    }
    const parsed = schema.safeParse(args ?? {});
    if (parsed.success) {
        const value = isRecord(parsed.data) ? parsed.data : record;
        return { ok: true, value };
    }
    const issues = parsed.error?.issues ?? [];
    const message = issues
        .map((issue) => {
        const path = issue.path.join(".");
        return path === "" ? issue.message : `${path}: ${issue.message}`;
    })
        .join("; ") || "invalid input";
    return { ok: false, message };
}
async function handle(message, serverName, tools, catalog) {
    const method = message.method;
    if (typeof method !== "string" || !("id" in message)) {
        return;
    }
    const id = message.id;
    const params = typeof message.params === "object" && message.params !== null ? message.params : {};
    try {
        if (method === "initialize") {
            const requested = params.protocolVersion;
            write({
                jsonrpc: "2.0",
                id,
                result: {
                    protocolVersion: typeof requested === "string" ? requested : PROTOCOL_VERSION,
                    capabilities: { tools: {} },
                    serverInfo: { name: serverName, version: "0.1.0" },
                },
            });
            return;
        }
        if (method === "ping") {
            write({ jsonrpc: "2.0", id, result: {} });
            return;
        }
        if (method === "tools/list") {
            write({
                jsonrpc: "2.0",
                id,
                result: {
                    tools: Object.entries(catalog).map(([name, entry]) => ({
                        name,
                        description: entry.description,
                        inputSchema: entry.inputSchema,
                        ...(entry.outputSchema === undefined ? {} : { outputSchema: entry.outputSchema }),
                    })),
                },
            });
            return;
        }
        if (method === "tools/call") {
            const name = params.name;
            const tool = typeof name === "string" ? tools[name] : undefined;
            if (tool === undefined) {
                write({
                    jsonrpc: "2.0",
                    id,
                    result: {
                        content: [{ type: "text", text: `Unknown tool: ${String(name)}` }],
                        isError: true,
                    },
                });
                return;
            }
            const checked = validateInput(tool, params.arguments);
            if (!checked.ok) {
                write({
                    jsonrpc: "2.0",
                    id,
                    result: {
                        content: [{ type: "text", text: checked.message }],
                        isError: true,
                    },
                });
                return;
            }
            const result = await tool.execute(checked.value);
            if (isMcpEnvelope(result)) {
                write({ jsonrpc: "2.0", id, result });
                return;
            }
            // A tool that advertises an outputSchema must return structuredContent
            // (MCP clients enforce this), so plain-object results ride along as
            // structuredContent next to the serialized text.
            const structuredContent = isRecord(result) ? result : undefined;
            write({
                jsonrpc: "2.0",
                id,
                result: {
                    content: [{ type: "text", text: stringifyResult(result) }],
                    ...(structuredContent === undefined ? {} : { structuredContent }),
                },
            });
            return;
        }
        write({
            jsonrpc: "2.0",
            id,
            error: { code: -32601, message: `Method not found: ${method}` },
        });
    }
    catch (error) {
        write({
            jsonrpc: "2.0",
            id,
            error: {
                code: -32603,
                message: error instanceof Error ? error.message : String(error),
            },
        });
    }
}
export function serveInlineStdioMcp(serverName, definition, catalog) {
    const tools = definition.tools ?? {};
    let buffer = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk) => {
        buffer += chunk;
        let newline = buffer.indexOf("\n");
        while (newline !== -1) {
            const line = buffer.slice(0, newline).replace(/\r$/, "");
            buffer = buffer.slice(newline + 1);
            if (line.length > 0) {
                try {
                    const message = readJsonRpc(JSON.parse(line));
                    if (message === undefined) {
                        continue;
                    }
                    void handle(message, serverName, tools, catalog);
                }
                catch (error) {
                    process.stderr.write(`${serverName}: failed to parse MCP message: ${error instanceof Error ? error.message : String(error)}\n`);
                }
            }
            newline = buffer.indexOf("\n");
        }
    });
}
